+import { verifySessionToken, SessionToken } from "./session-token.ts";
+import { isSessionRevoked } from "./revocation-cache.ts";
+
+export const validateSessionAtEdge = (token: SessionToken): boolean => {
+  if (!verifySessionToken(token)) {
+    return false;
+  }
+
+  if (isSessionRevoked(token.id)) {
+    return false;
+  }
+
+  return true;
+};
+
+export interface ValidatedSessionToken extends SessionToken {
+  valid: boolean;
+  userId: string;
+}
+
+export const validateAndExtract = (
+  token: SessionToken,
+): ValidatedSessionToken | null => {
+  const valid = validateSessionAtEdge(token);
+
+  if (!valid) {
+    return null;
+  }
+
+  return {
+    ...token,
+    valid: true,
+    userId: token.userId,
+  };
+};
