+// Main Service Usage
+
+import { loadSession, revokeSession } from "./session-store.ts";
+import { issueSessionToken } from "./session-token.ts";
+import { defaultRevocationSync } from "./revocation-sync.ts";
+
+// Initialize revocation sync on service startup
+await defaultRevocationSync.loadInitialRevocations();
+
+// When user logs in, create a session and issue token
+async function handleLogin(userId: string): Promise<string> {
+  // Create session in Postgres
+  const sessionId = generateId();
+
+  // Issue signed token to client
+  const token = issueSessionToken(sessionId, userId);
+
+  // Return token as JSON to client
+  return JSON.stringify(token);
+}
+
+// When user logs out, revoke the session
+async function handleLogout(sessionId: string): Promise<void> {
+  // Update Postgres and broadcast to edge workers
+  await revokeSession(sessionId);
+}
+
+// Main service validates sessions with DB access
+async function validateSessionMainService(
+  sessionId: string,
+): Promise<boolean> {
+  const session = await loadSession(sessionId);
+  return session !== null;
+}
+
+// ============================================================
+
+// Edge Worker Usage
+
+import { validateSessionAtEdge } from "./edge-session-validator.ts";
+import { SessionToken } from "./session-token.ts";
+
+// Parse token from incoming request header or body
+function extractTokenFromRequest(request: Request): SessionToken | null {
+  const token = request.headers.get("x-session-token");
+  if (!token) return null;
+
+  try {
+    return JSON.parse(token) as SessionToken;
+  } catch {
+    return null;
+  }
+}
+
+// Authenticate read API request
+export async function authenticate(request: Request): Promise<boolean> {
+  const token = extractTokenFromRequest(request);
+
+  if (!token) {
+    return false;
+  }
+
+  return validateSessionAtEdge(token);
+}
+
+// Example edge worker request handler
+export async function handleReadRequest(request: Request): Promise<Response> {
+  if (!await authenticate(request)) {
+    return new Response("Unauthorized", { status: 401 });
+  }
+
+  // Process authenticated request
+  const data = { status: "ok", message: "Read API working from edge" };
+  return new Response(JSON.stringify(data), { status: 200 });
+}
+
+// ============================================================
+
+// Helper function (would be in its own module)
+function generateId(): string {
+  return Math.random().toString(36).substring(2, 15);
+}
