+const REVOCATION_CHANNEL = "session:revoked";
+const REVOCATION_CACHE_TTL = 65 * 1000; // 65 seconds to cover 60-second SLA + buffer
+
+let revokedSessions = new Set<string>();
+let cacheTimestamp = 0;
+
+export const markSessionRevoked = (sessionId: string): void => {
+  revokedSessions.add(sessionId);
+};
+
+export const isSessionRevoked = (sessionId: string): boolean => {
+  return revokedSessions.has(sessionId);
+};
+
+export const getRevocationChannel = (): string => REVOCATION_CHANNEL;
+
+export const clearRevocationCache = (): void => {
+  revokedSessions.clear();
+  cacheTimestamp = 0;
+};
+
+export const getRevokedSessionIds = (): string[] => {
+  return Array.from(revokedSessions);
+};
+
+export const loadRevokedSessionIds = (sessionIds: string[]): void => {
+  revokedSessions = new Set(sessionIds);
+  cacheTimestamp = Date.now();
+};
