+import * as crypto from "crypto";
+
+const SESSION_SECRET = process.env.SESSION_SECRET || "default-secret";
+
+export interface SessionToken {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  signature: string;
+}
+
+export const issueSessionToken = (
+  id: string,
+  userId: string,
+): SessionToken => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const data = `${id}:${userId}:${issuedAt}`;
+  const signature = crypto
+    .createHmac("sha256", SESSION_SECRET)
+    .update(data)
+    .digest("hex");
+
+  return { id, userId, issuedAt, signature };
+};
+
+export const verifySessionToken = (token: SessionToken): boolean => {
+  const data = `${token.id}:${token.userId}:${token.issuedAt}`;
+  const expectedSignature = crypto
+    .createHmac("sha256", SESSION_SECRET)
+    .update(data)
+    .digest("hex");
+
+  return token.signature === expectedSignature;
+};
